'use strict';

/**
* Return a list of SGD loss functions.
*
* @module @stdlib/ml-base-sgd-loss-functions
*
* @example
* import lossFunctions from '@stdlib/ml-base-sgd-loss-functions';
*
* var list = lossFunctions();
* // e.g., returns [ 'epsilon-insensitive', 'hinge', 'huber', 'log', 'modified-huber', 'perceptron', 'squared-epsilon-insensitive', 'squared-error', 'squared-hinge' ]
*/

// MODULES //

import setReadOnly from '@stdlib/utils-define-nonenumerable-read-only-property';
import main from './main.js';
import enumeration from './enum.js';


// MAIN //

setReadOnly( main, 'enum', enumeration );


// EXPORTS //

export default main;
